using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
namespace DuckGame.Maps.V08 {
public sealed class MerchantShopUI:MonoBehaviour {
 public MerchantTrade trade;Canvas canvas;GameObject panel;Text balance,message,prompt;Text[] status=new Text[3];Font font;
 void Start(){font=Font.CreateDynamicFontFromOSFont(new[]{"Microsoft YaHei","SimHei","Noto Sans CJK SC"},24);var go=new GameObject("Merchant Chinese UI",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));go.transform.SetParent(transform,false);canvas=go.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=50;var scaler=go.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);if(FindObjectOfType<EventSystem>()==null)new GameObject("Trade EventSystem",typeof(EventSystem),typeof(StandaloneInputModule));prompt=Label(go.transform,"F  交易",new Vector2(0,-310),new Vector2(400,65),32,TextAnchor.MiddleCenter);panel=Box(go.transform,"Shop card",Vector2.zero,new Vector2(1040,690),new Color(.09f,.14f,.15f,.98f));Label(panel.transform,"苔苔的旅行小铺",new Vector2(-160,270),new Vector2(650,60),42,TextAnchor.MiddleLeft);Label(panel.transform,"林地补给  ·  升级立即生效",new Vector2(-160,210),new Vector2(650,45),23,TextAnchor.MiddleLeft);balance=Label(panel.transform,"",new Vector2(310,212),new Vector2(340,45),26,TextAnchor.MiddleRight);string[] names={"轻盈装填","顺风法球","同伴法球"};string[] desc={"射速 +20%  ·  最多购买3次","弹速 +25%  ·  最多购买3次","每次发射法球 +1  ·  最多8颗"};int[] prices={25,25,40};for(int i=0;i<3;i++){float y=100-i*125;var row=Box(panel.transform,"Product "+i,new Vector2(0,y),new Vector2(940,108),new Color(.16f,.23f,.23f));Label(row.transform,names[i],new Vector2(-290,23),new Vector2(310,42),30,TextAnchor.MiddleLeft);Label(row.transform,desc[i],new Vector2(-240,-23),new Vector2(410,35),21,TextAnchor.MiddleLeft);status[i]=Label(row.transform,"",new Vector2(105,0),new Vector2(230,45),22,TextAnchor.MiddleCenter);int k=i;Button(row.transform,prices[i]+" 金币  购买",new Vector2(342,0),new Vector2(205,62),()=>trade.TryPurchase(k));}message=Label(panel.transform,"",new Vector2(-70,-253),new Vector2(800,42),24,TextAnchor.MiddleLeft);Label(panel.transform,"试用金币仅本次游玩有效  ·  Esc / F 关闭",new Vector2(-20,-305),new Vector2(880,35),21,TextAnchor.MiddleCenter);Button(panel.transform,"关闭",new Vector2(414,278),new Vector2(130,52),trade.Close);Show(false);Refresh();}
 GameObject Box(Transform parent,string name,Vector2 pos,Vector2 size,Color color){var g=new GameObject(name,typeof(RectTransform),typeof(Image));g.transform.SetParent(parent,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.anchoredPosition=pos;r.sizeDelta=size;g.GetComponent<Image>().color=color;return g;}
 Text Label(Transform parent,string value,Vector2 pos,Vector2 size,int fontSize,TextAnchor align){var g=new GameObject(value,typeof(RectTransform),typeof(Text));g.transform.SetParent(parent,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.anchoredPosition=pos;r.sizeDelta=size;var t=g.GetComponent<Text>();t.text=value;t.font=font;t.fontSize=fontSize;t.alignment=align;t.color=new Color(.95f,.92f,.80f);t.raycastTarget=false;return t;}
 void Button(Transform p,string value,Vector2 pos,Vector2 size,UnityEngine.Events.UnityAction action){var g=Box(p,value,pos,size,new Color(.40f,.53f,.40f));g.AddComponent<Button>().onClick.AddListener(action);Label(g.transform,value,Vector2.zero,size,23,TextAnchor.MiddleCenter);}
 public void Show(bool show){if(panel!=null)panel.SetActive(show);if(prompt!=null)prompt.gameObject.SetActive(false);}
 public void Refresh(){if(balance==null)return;balance.text="试用金币  "+trade.Gold;message.text=trade.Message;for(int i=0;i<3;i++)status[i].text=trade.Status(i);}
 void Update(){if(prompt!=null)prompt.gameObject.SetActive(trade.CanInteract());}
}
}
